// Keeps the events of this recipe, then builds the request(s) for Mailchimp.
const WANTED = ["member.joined", "membership.started"]
const out = []
for (const item of $input.all()) {
  const msg = item.json.body ?? item.json
  if (WANTED.length && !WANTED.includes(msg.event)) continue
  const DC = 'us21' // the end of your API key, after the dash
  const LIST = 'abc123' // your audience id
  const u = msg.data.user ?? {}
  if (!u.email) continue
  // Mailchimp identifies a member by the MD5 of the lowercase e-mail
  const hash = require('crypto').createHash('md5').update(u.email.toLowerCase()).digest('hex')
  const base = `https://${DC}.api.mailchimp.com/3.0/lists/${LIST}/members/${hash}`
  const [first, ...rest] = (u.name ?? '').trim().split(/\s+/)
  // "transactional": in the audience without a marketing subscription (consent is asked by Mailchimp's own forms)
  out.push({ json: { method: 'PUT', url: base, body: { email_address: u.email, status_if_new: 'transactional', merge_fields: { FNAME: first ?? '', LNAME: rest.join(' ') } } } })
  const tags = [{ name: `learnfloo:${msg.space.slug}`, status: 'active' }]
  if (msg.event === 'membership.started') tags.push({ name: `learnfloo:${msg.space.slug}:paid`, status: 'active' })
  out.push({ json: { method: 'POST', url: `${base}/tags`, body: { tags } } })
}
return out
